mapper.select:
SELECT tc.id, tc.course_id, tc.course, tc.teacher_no, tc.course_credit, tc.capacity, ct.weekday, ct.start_section, ct.end_section,
CONVERT(VARCHAR, ISNULL(cct.course_type, tc.course_type)) IFNULL(cct.course_type, tc.course_type) as course_type, ct.location FROM teacher_course tc JOIN class_time ct ON tc.course_id = ct.course_id LEFT JOIN class_course_type cct ON tc.course_id = cct.course_id AND cct.class_id = #{className} AND cct.year = #{year} WHERE 1=1
AND tc.course = #{subject}
AND ISNULL(cct.course_type, tc.course_type) IFNULL(cct.course_type, tc.course_type) = #{courseType}
